text(await tools.exec_command({cmd:`cat > tmp/req-016/rusage.c <<'EOF'
#include <libproc.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/resource.h>

int main(int argc, char **argv) {
    for (int i = 1; i < argc; ++i) {
        int pid = atoi(argv[i]);
        struct rusage_info_v2 info;
        if (proc_pid_rusage(pid, RUSAGE_INFO_V2, (rusage_info_t *)&info) != 0) {
            perror(argv[i]);
            return 1;
        }
        printf("%d,%llu,%llu,%llu,%llu,%llu,%llu\\n", pid,
               info.ri_user_time + info.ri_system_time,
               info.ri_diskio_bytesread, info.ri_diskio_byteswritten,
               info.ri_phys_footprint, info.ri_pkg_idle_wkups,
               info.ri_proc_start_abstime);
    }
}
EOF
cc -Wall -Wextra -Werror tmp/req-016/rusage.c -o tmp/req-016/rusage &&
{
echo 'pid,cpu_ns,disk_read_bytes,disk_written_bytes,physical_footprint_bytes,package_idle_wakeups,start'
for i in {1..7}; do
date -u +%FT%TZ
tmp/req-016/rusage 50195 50199 50200 50201 || break
if [ "$i" -lt 7 ]; then sleep 10; fi
done
} > tmp/req-016/rusage.csv`,yield_time_ms:1000}))

