s=s[:start]+'''  const seed = join(fixture, "seed");
  await rename(join(fixture, "app"), seed);
  const variants = [
    ["before", resolve("tmp/req-016/native-contact-eval-before-batch")],
    ["after", resolve("target/release/examples/native-contact-eval")],
  ];
  for (const [name, executable] of variants) {
